package dental.flow.api.adapters.rest.out.persistence.entity;
import jakarta.persistence.*; import java.math.BigDecimal;
@Entity @Table(name="despesa") public class ExpenseEntity { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) @Column(name="id_despesa") private Long id; @Column(name="id_mapa_diario",nullable=false) private Long dailyMapId; @Column(name="descricao",nullable=false) private String description; @Column(name="valor") private BigDecimal value; public ExpenseEntity(){} public Long getId(){return id;} public void setId(Long v){id=v;} public Long getDailyMapId(){return dailyMapId;} public void setDailyMapId(Long v){dailyMapId=v;} public String getDescription(){return description;} public void setDescription(String v){description=v;} public BigDecimal getValue(){return value;} public void setValue(BigDecimal v){value=v;} }
